#!/usr/bin/env python3
"""Deterministic structural/semantic checks for the CVE-2020-10942 port.

Runs inside a clean checkout of the target commit with the candidate patch
applied (cwd == checkout root). Verifies the observable properties of the
get_raw_socket() hardening without requiring a kernel build.
"""
import re
import sys
from pathlib import Path

PATH = Path("drivers/vhost/net.c")

REQUIRED = [
    ("type check preserved", "sock->sk->sk_type != SOCK_RAW"),
    ("family check via sk_family", "sock->sk->sk_family != AF_PACKET"),
    ("err path releases socket", "sockfd_put(sock);"),
    ("err path returns r", "ERR_PTR(r)"),
]
FORBIDDEN = [
    ("no getname call", "getname"),
    ("no uaddr stack object", "uaddr"),
    ("no uaddr_len local", "uaddr_len"),
    ("no sockaddr_ll buffer", "sockaddr_ll"),
]


def function_body(text: str, name: str) -> str:
    start = text.index("static struct socket *" + name + "(int fd)")
    brace = text.index("{", start)
    depth = 0
    for idx in range(brace, len(text)):
        if text[idx] == "{":
            depth += 1
        elif text[idx] == "}":
            depth -= 1
            if depth == 0:
                return text[start:idx + 1]
    raise AssertionError("unbalanced braces in " + name)


def main() -> int:
    text = PATH.read_text(encoding="utf-8", errors="replace")
    body = function_body(text, "get_raw_socket")
    failures = []
    for label, needle in REQUIRED:
        if needle not in body:
            failures.append("missing required: %s (%r)" % (label, needle))
    for label, needle in FORBIDDEN:
        if needle in body:
            failures.append("forbidden present: %s (%r)" % (label, needle))
    if body.count("{") != body.count("}"):
        failures.append("unbalanced braces")
    if len(re.findall(r"\bAF_PACKET\b", body)) < 1:
        failures.append("AF_PACKET check absent")
    if failures:
        print("FAIL")
        for item in failures:
            print(" - " + item)
        return 1
    print("PASS: get_raw_socket hardens family validation without getname/stack buffer")
    print("function length: %d bytes" % len(body))
    return 0


if __name__ == "__main__":
    sys.exit(main())

